function Orders({ status, orders, error, retry }) {
  if (status === "loading") return <Skeleton rows={3} />;
  if (status === "error") return <ErrorBox message={error} onRetry={retry} />;
  if (orders.length === 0) return <Empty action="Créer une commande" />;
  return (
    <>
      {status === "partial" && <Notice>Certaines commandes n'ont pas pu charger.</Notice>}
      <ul>{orders.map(o => <li key={o.id}>{o.label}</li>)}</ul>
    </>
  );
}

